//! Constant-time oblivious generation of random permutations.
//!
//! A uniform random permutation is generated by sorting random keys through a
//! fixed sorting network (the construction used by djbsort and NTRU Prime):
//!
//! 1. **Pack**: build `[u64; N]` where `w[i] = (rng.next_u64() << 8) | i`.
//!    The high 56 bits are the random sort key; the low 8 bits carry the
//!    index as payload, so the sort routes the payload for free.
//! 2. **Sort**: run a Batcher odd-even mergesort network — a fixed,
//!    data-independent schedule of compare-exchange gates — with a branchless
//!    constant-time gate.
//! 3. **Collision check**: if any two random keys collide, the whole batch
//!    is rejected and generation **fails** — the seed must be discarded and a
//!    fresh one generated (see [`random_permutation`] for the lifecycle
//!    argument). A tie broken by the packed index would bias the output
//!    toward identity order, and patching only the colliding keys would leak
//!    *which* positions collided.
//! 4. **Strip**: the low bytes of the sorted array *are* the permutation.
//!
//! Instruction trace, memory trace, and per-instruction latency are functions
//! of `N` only: gate indices come from the public compile-time schedule, and
//! the comparison outcome is absorbed into a `subtle` select mask. No memory
//! address is ever derived from a secret value.

use subtle::{Choice, ConditionallySelectable, ConstantTimeEq, ConstantTimeGreater};
use vitaminc_random::{RandomError, Rng, SafeRand};
use zeroize::Zeroizing;

use crate::private::IsPermutable;

/// Number of compare-exchange gates in the Batcher odd-even mergesort network
/// for `n` inputs. Counting pass of [`batcher_schedule`]; for `n = 2^k` the
/// closed form is `(k² − k + 4)·2^(k−2) − 1`.
pub(crate) const fn batcher_gate_count(n: usize) -> usize {
    let mut gates = 0;
    let mut p = 1;
    while p < n {
        let mut k = p;
        loop {
            let mut j = k % p;
            while j + k < n {
                let mut i = 0;
                while i < k && i + j + k < n {
                    if (i + j) / (2 * p) == (i + j + k) / (2 * p) {
                        gates += 1;
                    }
                    i += 1;
                }
                j += 2 * k;
            }
            if k == 1 {
                break;
            }
            k /= 2;
        }
        p *= 2;
    }
    gates
}

/// The Batcher odd-even mergesort network for `n` inputs as a fixed schedule
/// of compare-exchange gates, generated at compile time (Knuth 5.3.4,
/// iterative form). The division guard keeps comparisons within the pair of
/// runs being merged. Correctness rests on the zero-one principle — a network
/// sorts everything iff it sorts all binary inputs — so the tests target this
/// transcription, not the theorem.
pub(crate) const fn batcher_schedule<const G: usize>(n: usize) -> [(u8, u8); G] {
    assert!(n <= 256, "gate indices must fit in u8");
    let mut out = [(0u8, 0u8); G];
    let mut gates = 0;
    let mut p = 1;
    while p < n {
        let mut k = p;
        loop {
            let mut j = k % p;
            while j + k < n {
                let mut i = 0;
                while i < k && i + j + k < n {
                    if (i + j) / (2 * p) == (i + j + k) / (2 * p) {
                        out[gates] = ((i + j) as u8, (i + j + k) as u8);
                        gates += 1;
                    }
                    i += 1;
                }
                j += 2 * k;
            }
            if k == 1 {
                break;
            }
            k /= 2;
        }
        p *= 2;
    }
    assert!(gates == G, "schedule length must match the gate count");
    out
}

/// Branchless compare-exchange: both locations are read and written
/// unconditionally on every gate, and the comparison outcome only ever feeds
/// a select mask (`cmov`/`csel`), never a branch or an address.
#[inline(always)]
fn compare_exchange(w: &mut [u64], a: usize, b: usize) {
    let (x, y) = (w[a], w[b]);
    let swap = x.ct_gt(&y);
    w[a] = u64::conditional_select(&x, &y, swap);
    w[b] = u64::conditional_select(&y, &x, swap);
}

/// Sorts `w` in place through the fixed network for `N`.
pub(crate) fn sort<const N: usize>(w: &mut [u64; N])
where
    [u8; N]: IsPermutable,
{
    for &(a, b) in <[u8; N]>::SCHEDULE {
        compare_exchange(w, a as usize, b as usize);
    }
}

/// Sorts a batch of packed words and extracts the permutation payload, or
/// returns `None` if any two random sort keys collide. Only the random bits
/// matter for collisions: the packed indices make the full words distinct,
/// and equal keys end up adjacent after sorting. The scan accumulates into a
/// mask so it is itself branch-free.
///
/// The extracted permutation is itself secret key material, so it is built
/// inside `Zeroizing` — the packed words being wiped is not enough.
fn permutation_from_words<const N: usize>(w: &mut [u64; N]) -> Option<Zeroizing<[u8; N]>>
where
    [u8; N]: IsPermutable,
{
    sort(w);
    let mut collision = Choice::from(0u8);
    for pair in w.windows(2) {
        collision |= (pair[0] >> 8).ct_eq(&(pair[1] >> 8));
    }
    if bool::from(collision) {
        return None;
    }
    let mut out: Zeroizing<[u8; N]> = Zeroizing::new([0; N]);
    for (o, x) in out.iter_mut().zip(w.iter()) {
        *o = (x & 0xFF) as u8;
    }
    Some(out)
}

/// Returns a uniform random permutation of `0..N` in gather form
/// (`out[j] = data[p[j]]` applies it), generated obliviously: timing and
/// memory access patterns are independent of the result.
///
/// Exactly **one** batch is attempted. On a key collision the whole batch is
/// rejected and generation fails with [`RandomError::SeedRejected`] — the
/// caller must discard the seed and start over with a fresh one, never retry
/// from the same RNG stream. Two reasons:
///
/// - The seed is typically a long-term secret that clients retain to
///   re-derive the permutation. A seed whose first batch collides can never
///   produce a stable permutation, so it is unusable by definition.
/// - Retrying in-stream would make runtime reveal whether the *retained*
///   seed collided — a predicate of the secret seed. Failing after one batch
///   moves the retry to the seed-generation layer, where timing reveals only
///   how many independent, discarded seeds preceded the accepted one.
///
/// With 56 random bits the collision probability is ≈ N²/2⁵⁷ (≈ 2⁻⁴³ at
/// N = 128), so honest generation essentially never fails.
pub(crate) fn random_permutation<const N: usize>(
    rng: &mut SafeRand,
) -> Result<Zeroizing<[u8; N]>, RandomError>
where
    [u8; N]: IsPermutable,
{
    // The payload (and the schedule's gate indices) are single bytes.
    const { assert!(N <= 256, "permutation length must fit in u8") };
    let mut w: Zeroizing<[u64; N]> = Zeroizing::new([0; N]);
    for (i, slot) in w.iter_mut().enumerate() {
        *slot = (rng.next_u64() << 8) | i as u64;
    }
    permutation_from_words(&mut w).ok_or(RandomError::SeedRejected)
}

#[cfg(test)]
mod tests {
    use super::*;
    use vitaminc_random::SeedableRng;

    fn is_sorted(w: &[u64]) -> bool {
        w.windows(2).all(|p| p[0] <= p[1])
    }

    fn assert_is_permutation<const N: usize>(p: &[u8; N]) {
        let mut seen = [false; N];
        for &v in p {
            assert!((v as usize) < N, "value {v} out of range");
            assert!(!seen[v as usize], "value {v} repeated");
            seen[v as usize] = true;
        }
    }

    #[test]
    fn gate_counts_match_closed_form() {
        // (k² − k + 4)·2^(k−2) − 1 for n = 2^k.
        for (n, expected) in [
            (2, 1),
            (4, 5),
            (8, 19),
            (16, 63),
            (32, 191),
            (64, 543),
            (128, 1471),
        ] {
            assert_eq!(batcher_gate_count(n), expected, "gate count for n = {n}");
        }
    }

    #[test]
    fn schedule_gates_are_in_bounds_and_ordered() {
        fn check<const N: usize>()
        where
            [u8; N]: IsPermutable,
        {
            for &(a, b) in <[u8; N]>::SCHEDULE {
                assert!(a < b, "gate ({a}, {b}) not ordered");
                assert!((b as usize) < N, "gate ({a}, {b}) out of bounds for {N}");
            }
        }
        check::<8>();
        check::<16>();
        check::<32>();
        check::<64>();
        check::<128>();
    }

    #[test]
    fn network_sorts_all_binary_inputs() {
        // Zero-one principle: a comparison network sorts every input iff it
        // sorts all binary inputs. Exhaustive at N = 8 and N = 16.
        for bits in 0u32..(1 << 8) {
            let mut w: [u64; 8] = core::array::from_fn(|i| u64::from(bits >> i) & 1);
            sort(&mut w);
            assert!(is_sorted(&w), "failed on binary input {bits:#010b}");
        }
        for bits in 0u32..(1 << 16) {
            let mut w: [u64; 16] = core::array::from_fn(|i| u64::from(bits >> i) & 1);
            sort(&mut w);
            assert!(is_sorted(&w), "failed on binary input {bits:#018b}");
        }
    }

    #[test]
    fn network_sorts_random_words() {
        // Every supported length: the zero-one tests only cover 8/16, and a
        // length-specific transcription bug would otherwise go unnoticed.
        fn check<const N: usize>(rng: &mut SafeRand)
        where
            [u8; N]: IsPermutable,
        {
            for _ in 0..100 {
                let mut w: [u64; N] = core::array::from_fn(|_| rng.next_u64());
                let mut expected = w;
                expected.sort_unstable();
                sort(&mut w);
                assert_eq!(w, expected);
            }
        }
        let mut rng = SafeRand::from_seed([42u8; 32]);
        check::<8>(&mut rng);
        check::<16>(&mut rng);
        check::<32>(&mut rng);
        check::<64>(&mut rng);
        check::<128>(&mut rng);
    }

    #[test]
    fn output_is_a_valid_permutation() {
        fn check<const N: usize>(rng: &mut SafeRand)
        where
            [u8; N]: IsPermutable,
        {
            for _ in 0..50 {
                assert_is_permutation(&random_permutation::<N>(rng).unwrap());
            }
        }
        let mut rng = SafeRand::from_seed([9u8; 32]);
        check::<8>(&mut rng);
        check::<16>(&mut rng);
        check::<32>(&mut rng);
        check::<64>(&mut rng);
        check::<128>(&mut rng);
    }

    #[test]
    fn colliding_keys_reject_the_batch() {
        // Two equal random keys (high 56 bits) with different payloads must
        // reject the whole batch, even though the packed words are distinct.
        let mut w: [u64; 8] = core::array::from_fn(|i| ((i as u64) << 8) | i as u64);
        w[3] = (7 << 8) | 3; // same sort key as w[7], different payload
        assert!(permutation_from_words(&mut w).is_none());

        // Distinct keys must produce the payload permutation in sorted-key
        // order: descending keys reverse the payloads.
        let mut w: [u64; 8] = core::array::from_fn(|i| ((7 - i as u64) << 8) | i as u64);
        assert_eq!(
            permutation_from_words(&mut w).map(|z| *z),
            Some([7, 6, 5, 4, 3, 2, 1, 0])
        );
    }

    #[test]
    fn output_is_deterministic_for_a_seed() {
        let a = random_permutation::<64>(&mut SafeRand::from_seed([1u8; 32])).unwrap();
        let b = random_permutation::<64>(&mut SafeRand::from_seed([1u8; 32])).unwrap();
        assert_eq!(*a, *b);
    }
}
